/* Wrap the EJS CONSTRUCTOR: the minified react lab.js bundle calls
   new EJS({url:…}) directly (its own .action-configsget handler +
   printFormNodeConfigs), and the live compiler eval()s — blocked by CSP,
   and the thrown EvalError aborts jQuery's delegated-handler chain, which
   is how the Startup Configs click died silently. Any caller whose url is
   in the precompiled set gets the offline-compiled function; everything
   else falls through to the original (only works with CSP off/report). */
(function () {
  function install() {
    var Orig = window.EJS;
    if (!Orig || Orig.__pnqWrapped) return !!Orig;
    function WrappedEJS(options) {
      var url = options && options.url;
      if (url && !options.precompiled) {
        var fn = window.PNQ_EJS_PRECOMPILED[url];
        if (fn) return new Orig({ precompiled: fn, name: url });
      }
      return new Orig(options);
    }
    WrappedEJS.prototype = Orig.prototype;
    for (var k in Orig) if (Object.prototype.hasOwnProperty.call(Orig, k)) WrappedEJS[k] = Orig[k];
    WrappedEJS.__pnqWrapped = true;
    window.EJS = WrappedEJS;
    return true;
  }
  // ejs.js is a DEFERRED script — this file must also be deferred and later in
  // the document; the retries below are belt-and-braces if ordering changes.
  if (!install()) {
    document.addEventListener('DOMContentLoaded', install);
    window.addEventListener('load', install);
  }
})();

/* drop-in for: new EJS({ url: <url> }) — explicit lookup so the engine call
   sites work even if the constructor wrapper could not install. */
window.pnqEjs = function (url) {
  var fn = window.PNQ_EJS_PRECOMPILED[url];
  if (fn) return new EJS({ precompiled: fn, name: url });
  return new EJS({ url: url });
};
